#include <string.h>
#include <stdlib.h>

// Function to retrieve and send a floorplan image
void send_floorplan_image(WebEmSession* session, const request* req, reply* rep) {
    const char* idx_str = request_get_param(req, "idx");
    if (!idx_str || idx_str[0] == '\0') {
        return; // Exit early if idx is empty
    }

    char* endptr;
    unsigned long idx = strtoul(idx_str, &endptr, 10);
    if (*endptr != '\0') {
        return; // Exit if idx is not a valid number
    }

    // Query the database for the image associated with the given ID
    unsigned char* image_data = NULL;
    size_t image_size = 0;
    if (!query_database_for_image(idx, &image_data, &image_size)) {
        return; // Exit if no image is found
    }

    // Validate image data and size
    if (!image_data || image_size == 0) {
        free(image_data);
        return;
    }

    // Determine file extension based on the first byte
    const char* file_extension = "png";
    if (image_size > 0) {
        switch (image_data[0]) {
            case 'G': // GIF
                file_extension = "gif";
                break;
            case 'P': // PNG
                file_extension = "png";
                break;
            case '\377': // JPEG
                file_extension = "jpg";
                break;
            default:
                file_extension = "png";
                break;
        }
    }

    // Set the content of the reply with the image data
    reply_set_content(rep, image_data, image_size);

    // Add the attachment header with the file extension
    char content_disposition[256];
    snprintf(content_disposition, sizeof(content_disposition), "attachment; filename=floorplan.%s", file_extension);
    reply_set_header(rep, "Content-Disposition", content_disposition);

    // Free the allocated image data
    free(image_data);
}
